INSERT INTO "public"."quiz_questions" ("id", "module_id", "question_number", "question_type", "question_text", "options", "correct_answer", "explanation", "created_at") VALUES ('a1b2c3d4-0001-0002-0001-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '1', 'multiple-choice', 'What are the minimum and preferred photo resolutions for inspection photos?', '["800x600 minimum, 1024x768 preferred","1024x768 minimum, 1600x1200 preferred","1600x1200 minimum, 2048x1536 preferred","640x480 minimum, 800x600 preferred"]', '1', 'The industry standard requires a minimum of 1024x768 pixels, with 1600x1200 preferred for clarity in documentation.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0001-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '2', 'multiple-choice', 'What is the required aspect ratio for all inspection photos?', '["16:9","4:3","1:1","3:2"]', '1', 'A 4:3 aspect ratio is required as it provides the best balance for property documentation and is standard across most inspection portals.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0001-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '3', 'multiple-choice', 'How many different mapping programs must be used before marking a property as "Unable to Locate"?', '["One","Two","Three","Four"]', '2', 'Three different mapping programs must be consulted to verify the address cannot be found before marking a case as unable to locate.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0001-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '4', 'multiple-choice', 'What is the maximum allowable baluster spacing before it is considered a safety hazard?', '["2 inches","4 inches","6 inches","8 inches"]', '1', 'Baluster spacing greater than 4 inches is considered a hazard per building codes, as small children could fit through wider gaps.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0001-000000000005', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '5', 'multiple-choice', 'When should you begin taking photos at a property?', '["Immediately upon arrival","After parking in the driveway","After knocking on the door to check if someone is home","After completing the full exterior walk"]', '2', 'You should not take any photos until after you have knocked on the door to see if the insured is present, allowing you to introduce yourself and explain the inspection.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0001-000000000006', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '6', 'multiple-choice', 'What items must NEVER appear in inspection photos?', '["Vehicles and landscaping","People and time/date stamps","Street signs and house numbers","Fences and outbuildings"]', '1', 'Photos must never include people (privacy/liability) or burned-in time/date stamps (can be manipulated and create legal issues).', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0001-000000000007', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '7', 'multiple-choice', 'What is the recommended sequence for exterior photos?', '["Random order based on obstacles","Start at back, move to front","Start at front with address, then clockwise or counter-clockwise","Start at the roof, work down"]', '2', 'Start at the front for the address shot, then move systematically clockwise or counter-clockwise to ensure no elevation is missed.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0001-000000000008', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '8', 'multiple-choice', 'What does PCR stand for in field services?', '["Property Condition Report","Professional Certified Review","Primary Client Request","Pre-Closing Review"]', '0', 'PCR stands for Property Condition Report, a standardized form documenting property status used throughout the industry.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0002-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '9', 'true-false', 'Vertical (portrait) orientation photos are acceptable if they better capture a tall structure.', '["True","False"]', '1', 'ALL photos must be horizontal (landscape). Vertical photos are the #1 reason for rejected reports. Step back farther to capture tall structures.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0002-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '10', 'true-false', 'If an occupant asks you to leave, you should explain the importance of the inspection and continue.', '["True","False"]', '1', 'If someone asks you to leave, you must apologize and leave immediately. Never argue or continue photographing. Document the refusal and contact your client.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0002-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '11', 'true-false', 'Field inspectors should diagnose the cause of damage they observe.', '["True","False"]', '1', 'Field inspectors document WHAT they see, not WHY. Diagnosing causes is outside your scope and creates liability. Use phrases like "appears to be" instead.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0003-000000000001', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '12', 'scenario', 'You arrive at a property and an aggressive dog is loose in the yard. The dog is not secured and the owner does not appear to be home. What should you do?', '["Try to make friends with the dog using treats","Take photos from the public sidewalk if possible, note ''dog on property'' in your report, and do not approach","Climb the fence to complete the inspection","Call animal control to have the dog removed"]', '1', 'Never put yourself at risk. Document what you can from a safe distance (public property), note the hazard, and contact your client for guidance on next steps.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0003-000000000002', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '13', 'scenario', 'After leaving a property, you realize your photos are blurry and unusable. The SLA is in 4 hours. What is your best course of action?', '["Submit the blurry photos and hope the client does not notice","Return to the property immediately to retake the photos","Contact the client and request a 24-hour extension","Mark the case as ''unable to complete'' without explanation"]', '1', 'If time permits, return immediately to retake photos. Submitting poor quality work damages your reputation more than requesting an extension.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0003-000000000003', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '14', 'scenario', 'You observe water staining on a ceiling during an interior inspection. How should you document this?', '["Water damage caused by roof leak","Staining observed on ceiling - appears to be water damage","Roof needs replacement due to leaking","Plumbing failure has caused ceiling damage"]', '1', 'Document what you SEE, not what you THINK caused it. "Staining observed" with qualifier "appears to be" is correct. Diagnosing the cause is outside your scope.', '2026-01-29 23:43:11.85101+00'), ('a1b2c3d4-0001-0002-0003-000000000004', 'a1b2c3d4-e5f6-7890-abcd-000000000001', '15', 'scenario', 'You complete an inspection but the GPS took you to a property that does not match the description. The address number is not visible on the house. What should you do?', '["Submit the inspection anyway since you went to where GPS said","Leave without documenting anything","Do NOT proceed - verify the correct property using multiple mapping sources and contact client if unable to confirm","Take photos of whatever house you are at"]', '2', 'Wrong address inspections are a top chargeback reason. If you cannot verify the address, do NOT proceed. Use multiple mapping sources and contact your client for guidance.', '2026-01-29 23:43:11.85101+00');